import anthropic
import json

client = anthropic.Anthropic()

# Define tools the agent can use
tools = [
    {
        "name": "web_search",
        "description": "Search the web for current information. Use for facts, news, prices.",
        "input_schema": {"type": "object", "properties": {
            "query": {"type": "string", "description": "Search query"}
        }, "required": ["query"]}
    },
    {
        "name": "calculator",
        "description": "Evaluate a mathematical expression. Input must be a Python expression string.",
        "input_schema": {"type": "object", "properties": {
            "expression": {"type": "string", "description": "e.g. '2 ** 10 + 3 * 7'"}
        }, "required": ["expression"]}
    }
]

def execute_tool(name: str, input_data: dict) -> str:
    """Execute a tool and return the result as a string."""
    if name == "web_search":
        return f"[Search results for '{input_data['query']}': Revenue grew 18% YoY to $2.4M]"  # stub
    elif name == "calculator":
        try:
            return str(eval(input_data["expression"], {"__builtins__": {}}))
        except Exception as e:
            return f"Error: {e}"
    return "Tool not found"

def run_agent(goal: str, max_iterations: int = 10) -> str:
    messages = [{"role": "user", "content": goal}]

    for iteration in range(max_iterations):
        response = client.messages.create(
            model="claude-opus-4-5",
            max_tokens=4096,
            tools=tools,
            messages=messages
        )

        if response.stop_reason == "end_turn":
            # Agent is done — extract final text
            return next((b.text for b in response.content if hasattr(b, "text")), "")

        # Execute all tool calls in this response
        tool_results = []
        for block in response.content:
            if block.type == "tool_use":
                result = execute_tool(block.name, block.input)
                tool_results.append({
                    "type": "tool_result",
                    "tool_use_id": block.id,
                    "content": result
                })

        # Append assistant response + tool results to messages
        messages.append({"role": "assistant", "content": response.content})
        messages.append({"role": "user", "content": tool_results})

    return "Max iterations reached"

result = run_agent("What is 18% of Acme Corp's Q3 revenue if they had $2.4M total revenue?")
print(result)
